CREATE TABLE "c_Booking" ("id" BIGINT NOT NULL, "a_Booking_booked_at" TIMESTAMP NOT NULL, "a_Booking_status" TEXT NOT NULL, "r_TravelerBookings_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_TravelerBookings_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_TravelerBookings_source_id" IS NOT NULL));
CREATE TABLE "c_FlightSegment" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_FlightSegment_flight_no" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('FlightSegment')));
CREATE TABLE "c_HotelStay" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_HotelStay_hotel_name" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('HotelStay')));
CREATE TABLE "c_ItineraryItem" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_ItineraryItem_start_time" TIMESTAMP NOT NULL, "r_BookingItems_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('FlightSegment','HotelStay','ItineraryItem')), CHECK ((dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "r_BookingItems_source_id" IS NULL), CHECK (NOT (dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "r_BookingItems_source_id" IS NOT NULL));
CREATE TABLE "c_Payment" ("id" BIGINT NOT NULL, "a_Payment_amount" NUMERIC NOT NULL, "r_BookingPayments_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_BookingPayments_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_BookingPayments_source_id" IS NOT NULL));
CREATE TABLE "c_Traveler" ("id" BIGINT NOT NULL, "a_Traveler_name" TEXT NOT NULL, PRIMARY KEY ("id"));
ALTER TABLE "c_Booking" ADD CONSTRAINT "fk_c_Booking_0" FOREIGN KEY ("r_TravelerBookings_source_id") REFERENCES "c_Traveler" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_FlightSegment" ADD CONSTRAINT "fk_c_FlightSegment_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_ItineraryItem" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_HotelStay" ADD CONSTRAINT "fk_c_HotelStay_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_ItineraryItem" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_ItineraryItem" ADD CONSTRAINT "fk_c_ItineraryItem_0" FOREIGN KEY ("r_BookingItems_source_id") REFERENCES "c_Booking" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Payment" ADD CONSTRAINT "fk_c_Payment_0" FOREIGN KEY ("r_BookingPayments_source_id") REFERENCES "c_Booking" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;